// break_mcycle_write.S
//
// Bug: writing mcycle inside the ROI silently corrupts the reported cycle
// figure.  The cycle delta = (drained mcycle) - (mcycle_at_measure_start).
// If the ROI resets mcycle to zero, the drained value is near-zero regardless
// of how much real work the ROI did; the delta underflows (if a warmup
// baseline was captured) or collapses to near-zero (default, no warmup).
//
// Nothing in the hybrid runtime prevents a bare-metal program from writing
// mcycle.  A performance-measurement library that resets the counter at the
// start of a timed region would trigger this silently.
//
// Expected outcome:
//   Plain hybrid run: completes normally, reported cycles << actual ROI work.
//   VERIFY=1: also completes, but cycle fields are masked so no compare fires.
//   The wrong number is invisible unless the user inspects the raw state file.
//
// Scope: bare-metal, no async interrupts.

.section .text
.globl _start
_start:
    // Burn some cycles pre-ROI so QEMU1's drained mcycle is non-trivial.
    li   t0, 0
    li   t1, 10000
pre_loop:
    addi t0, t0, 1
    blt  t0, t1, pre_loop

    slti x0, x0, 0x5A0          // ENTER ROI

    csrw mcycle, zero            // reset the cycle counter <- THE BUG
    // mcycle is now 0 (or 1).  StateDrain re-reads it at the exit marker.
    // The reported window_cycles = (near-zero) - (entry baseline) = WRONG.

    // ROI work: 10000-iteration loop that should cost ~30000+ RTL cycles.
    li   t0, 0
    li   t1, 10000
roi_loop:
    addi t0, t0, 1
    mul  t2, t0, t0             // mul to stretch pipeline (result discarded)
    blt  t0, t1, roi_loop

    slti x0, x0, 0x5A1          // EXIT ROI

    li   t0, 0xe0080000
    sw   x0, 0(t0)
1:  j    1b

// break_verify_diverge.S
//
// Bug: code inside the ROI that branches on (mcycle - minstret) will diverge
// between a hybrid run and the VERIFY=1 oracle.
//
// Mechanism:
//   vsim (RTL): counts actual clock cycles including pipeline stalls and cache
//               miss penalties.  For 1000 cache-striding loads:
//               mcycle_delta >> minstret_delta (stall cycles accumulate).
//   QEMU oracle: models CPI=1 for most instructions; mcycle_delta ≈ minstret_delta.
//
// The overhead = (mcycle_delta - minstret_delta) reliably separates the two:
//   QEMU oracle:  overhead ≈ 0  -> branch NOT taken -> a0 = 0xAAAA
//   vsim:         overhead >> 0 -> branch taken     -> a0 = 0xBBBB
//
// --verify then fires: "[state-diff] x10: ref=0xAAAA... got=0xBBBB..."
//
// The plain hybrid run always produces one fixed result (vsim is deterministic).
// Only --verify exposes the divergence.
//
// Scope: bare-metal, no async interrupts.

.section .text
.globl _start
_start:
    // Stash minstret and mcycle just before the ROI so we can compute deltas
    // inside the ROI (both are restored from QEMU1 drain = same baseline).
    csrr s0, minstret
    csrr s1, mcycle

    slti x0, x0, 0x5A0          // ENTER ROI
    // s0 = entry minstret, s1 = entry mcycle (restored from QEMU1 drain).

    // 1000 loads with 64-byte stride across the low 64 KB of DRAM.
    // Each load is a cold cache miss in vsim (L1 D-cache thrashing).
    // QEMU counts 1 cycle per instruction; vsim counts ~50+ stall cycles per miss.
    li   t0, 0                  // loop counter
    li   t1, 1000
    li   t2, 0                  // load address (starts at 0x00000000 = valid DRAM)
cache_stride_loop:
    lw   zero, 0(t2)            // cache-miss load; stalls vsim pipeline
    addi t2, t2, 64             // next cache line
    addi t0, t0, 1
    blt  t0, t1, cache_stride_loop

    csrr a0, mcycle
    csrr a1, minstret
    sub  a0, a0, s1             // mcycle_delta
    sub  a1, a1, s0             // minstret_delta
    sub  a0, a0, a1             // overhead = mcycle_delta - minstret_delta

    // QEMU oracle:  overhead ≈ 0 (CPI=1 model)
    // vsim:         overhead >> 0 (real cache-miss stall cycles)
    bnez a0, stalled
    li   a0, 0xAAAAAAAAAAAAAAAA  // oracle path: no stall overhead
    j    done
stalled:
    li   a0, 0xBBBBBBBBBBBBBBBB // hybrid path: stall cycles observed

done:
    slti x0, x0, 0x5A1          // EXIT ROI
    // --verify: oracle a0=0xAAAA, hybrid a0=0xBBBB -> FAIL

    li   t0, 0xe0080000
    sw   x0, 0(t0)
1:  j    1b

// break_vscratch.S
//
// Bug: kVScratchGpa (0x00FF0000) is unconditionally overwritten by the V
// register transport during ResumeDriver::resume() on every V-capable core,
// even for programs that never execute a V instruction.  User data placed at
// that address is silently corrupted before the ROI runs its first instruction.
//
// The linker script marks 0x00FF0000 as V_SCRATCH in its comment, but there is
// no hardware guard and no documented trap for programs that access it directly.
//
// Expected outcome (V-capable core, e.g. ax45mpv_premium):
//   - ResumeDriver::pb_v_data_sweep loads v0..v31 FROM 0x00FF0000 into the
//     vector regfile.  stage_v_to_scratch wrote vreg[] (QEMU1-drained bytes,
//     usually zeros for a program that never used V) into that region first.
//   - The sentinel 0xDEADBEEFCAFEBABE is gone; in-ROI check fires -> hang.
//   - Harness timeout -> FAIL.
//
// Expected outcome (non-V core or HYBRID_FLAG_V not set): PASS (no transport).
//
// Scope: bare-metal, no async interrupts.

.section .text
.globl _start
_start:
    // Write a known sentinel to kVScratchGpa before the ROI.
    li   t0, 0x00FF0000
    li   t1, 0xDEADBEEFCAFEBABE
    sd   t1, 0(t0)              // sentinel lives at scratch GPA

    // t0 and t1 survive the GPR restore because they are drained here by
    // QEMU1 and restored after the V sweep (ResumeDriver restores GPRs last).
    slti x0, x0, 0x5A0          // ENTER ROI

    // After resume: V transport wrote v0's register bytes to 0x00FF0000.
    // On a fresh program that never used V, those bytes are zeros (QEMU1
    // drained v0..v31 = zero).
    ld   t2, 0(t0)              // reload from scratch GPA
    bne  t2, t1, regress        // corrupted? -> infinite loop -> harness FAIL

    slti x0, x0, 0x5A1          // EXIT ROI (only reached if V transport absent)

    li   t0, 0xe0080000         // SimControl: exit code 0 for standalone run
    sw   x0, 0(t0)
1:  j    1b

regress:
    j    regress                // V transport clobbered sentinel -> hang

// rt_trap_ecall.S
//
// Lock-step DV gate fixture (cosim_redesign F6). A self-contained,
// self-initializing testbench: it writes EVERY GPR to a known value before
// the ROI, so the QEMU-vs-RTL reset-state difference (QEMU seeds a0/a1/.. with
// boot args; the RTL resets GPRs to 0) has vanished by the arm point. Lock-step
// arms at `roi_start` (`--pc-start roi_start`), so the init prologue executes
// on both engines but is not recorded; record 0 is the ROI's first attempt
// with identical architectural state on both sides.
//
// The ROI exercises the trap path the PM decision (traps in scope) requires:
// two M-mode ecalls, each trapping to a handler that bumps mepc by 4 and
// mret's back. At each handler-entry attempt mcause==11 (ecall-from-M) and
// mepc are compared across the engines (lock-step diff compares the trap
// cause), so a mishandled trap on the DUT would diverge loudly. Exit is via
// the SimControl device (0xe0080000), which both QEMU's andes_ae350 and vsim
// model -- no semihosting, so the same ELF lock-steps on both legs.

.section .text
.globl _start
_start:
    // Trap vector -> trap_handler (Direct mode: low 2 bits 0).
    la      t0, trap_handler
    csrw    mtvec, t0

    // Initialize every GPR x1..x31 to a known value. After this, the two
    // engines agree on all architectural registers regardless of reset
    // conventions, so the ROI comparison starts from a common state.
    li      x1,  0x101
    li      x2,  0x202
    li      x3,  0x303
    li      x4,  0x404
    li      x5,  0x505
    li      x6,  0x606
    li      x7,  0x707
    li      x8,  0x808
    li      x9,  0x909
    li      x10, 0x0a0a
    li      x11, 0x0b0b
    li      x12, 0x0c0c
    li      x13, 0x0d0d
    li      x14, 0x0e0e
    li      x15, 0x0f0f
    li      x16, 0x1010
    li      x17, 0x1111
    li      x18, 0x1212
    li      x19, 0x1313
    li      x20, 0x1414
    li      x21, 0x1515
    li      x22, 0x1616
    li      x23, 0x1717
    li      x24, 0x1818
    li      x25, 0x1919
    li      x26, 0x1a1a
    li      x27, 0x1b1b
    li      x28, 0x1c1c
    li      x29, 0x1d1d
    li      x30, 0x1e1e
    li      x31, 0x1f1f

.globl roi_start
roi_start:
    // Straight-line work + two trapping ecalls. Each ecall: mcause=11,
    // mepc=<ecall pc>; the handler advances mepc by 4 and returns.
    addi    a0, a0, 1
    ecall
    addi    a1, a1, 2
    ecall
    add     a2, a0, a1

    // Exit 0 via SimControl (works on both engines).
    li      t3, 0xe0080000
    sw      x0, 0(t3)
hang:
    j       hang

// Synchronous trap handler: skip the trapping instruction (all traps here are
// 4-byte ecalls) and return. Reads mcause/mepc into GPRs so the values also
// surface in the compared register file.
.align 2
trap_handler:
    csrr    t1, mcause
    csrr    t2, mepc
    addi    t2, t2, 4
    csrw    mepc, t2
    mret

