// break_lrsc.S
//
// Bug: an LR/SC reservation cannot cross the QEMU1 -> vsim handoff. The
// reservation is microarchitectural state, not part of hybrid_state_v1
// (include/hybrid/state_abi.h has no reservation field), so it never
// round-trips. If `lr.d` retires on the QEMU1 leg and the matching `sc.d`
// retires on the vsim leg, vsim resumed with no live reservation and the
// store-conditional ALWAYS fails. A lock-free CAS loop built on lr/sc that
// straddles the trigger spins forever.
//
// This fixture holds a reservation across the ENTER marker:
//   lr.d   (QEMU1 leg)   acquires a reservation on `lock`
//   slti x0,x0,0x5A0     ENTER ROI -> QEMU1 drains, vsim resumes (no reservation)
//   sc.d   (vsim leg)    store-conditional; vsim has no reservation -> FAIL
//
// Only one non-memory instruction (the marker HINT) sits between the lr and
// the sc, so on a SINGLE engine the reservation survives and the sc succeeds.
// The asymmetry isolates the handoff boundary as the sole cause:
//   Standalone (--model fast OR cycle): sc.d succeeds (rc=0) -> exit 0 -> PASS.
//   Hybrid (--model hybrid):            sc.d fails    (rc!=0) -> hang  -> FAIL.
//
// Scope: bare-metal, no async interrupts; A extension (rv64gc).

.section .text
.globl _start
_start:
    la   a0, lock              // reservation address (lives in the shared mmap)
    li   t2, 0xA5A5A5A5         // value to store-conditionally

    lr.d t0, (a0)              // acquire reservation on `lock` (QEMU1 leg)

    slti x0, x0, 0x5A0         // ENTER ROI -- handoff drains here; reservation lost

    sc.d t1, t2, (a0)          // store-conditional on the vsim leg
    // t1 == 0 -> sc succeeded (reservation survived); t1 != 0 -> sc failed.
    bnez t1, regress           // failed (the bug) -> hang -> harness FAIL

    slti x0, x0, 0x5A1         // EXIT ROI (reached only if the reservation survived)

    li   t0, 0xe0080000        // SimControl: exit code 0 for a standalone run
    sw   x0, 0(t0)
1:  j    1b

regress:
    j    regress               // reservation lost across the handoff -> hang

.section .data
.align 3
lock:
    .dword 0

