cd /home/nick/work/hybrid_sim
cat /tmp/nbexec.log
echo "================ demo-cell outputs from executed notebook ================"
python3 -c "
import json
nb=json.load(open('/tmp/limitations_executed.ipynb'))
def text(c):
    out=[]
    for o in c.get('outputs',[]):
        if 'text' in o: out.append(''.join(o['text']))
        elif o.get('output_type')=='stream': out.append(''.join(o.get('text',[])))
        elif 'data' in o and 'text/plain' in o['data']: out.append(''.join(o['data']['text/plain']))
        if o.get('output_type')=='error': out.append('ERROR: '+o.get('ename','')+': '+''.join(o.get('evalue','')))
    return ''.join(out)
for i,c in enumerate(nb['cells']):
    if c['cell_type']!='code': continue
    src=''.join(c['source'])
    tag=src.strip().splitlines()[0][:60]
    o=text(c).strip()
    print(f'--- code cell {i}: {tag}')
    print(o[:600] if o else '(no output)')
    print()
"
